  'result.benefit_duration': 'How long',
  'result.benefit_contributed': 'Days of contributions',
  'result.benefit_deadline': 'How and when to apply',
  'result.benefit_deadline_text':
    "Without registering as a jobseeker there is no unemployment benefit: you register with your region's employment service and apply to SEPE for the benefit within the 15 days after the contract ends (business days, according to SEPE). If your final settlement pays untaken holiday, the time limit runs from when those days end; if you apply late, you lose the days of delay (arts. 266 and 268 LGSS).",
  'result.benefit_work_history':
    'Your employment history (vida laboral) shows each start and leaving date and the days of contributions:',
  'result.benefit_work_history_link':
    'your employment history report (informe de vida laboral, Seguridad Social online office)',
  'result.benefit_just_cause':
    'There are exceptions. Leaving for one of these reasons does count as a legal situation of unemployment and, if you meet the other requirements, gives entitlement to unemployment benefit: a relocation (art. 40 ET), a substantial change to your conditions that harms you (art. 41.3 ET), a serious breach by the employer, such as not paying you or paying you late again and again (art. 50 ET), or gender-based or sexual violence (art. 49.1.m ET). This is set out in art. 267.1.a.5.º LGSS. Leaving under art. 50 is usually declared by a court.',
  'result.benefit_calculation':
    'The base is the average of unemployment contributions over the last 180 days; here it comes from your gross annual pay with extra payments, divided by 12, within the minimum and maximum bases for 2026. You receive 70 % of the base for the first 180 days and 60 % after that, with a minimum and a maximum depending on your dependent sons or daughters. The duration follows the scale in art. 269.1: 360 days of contributions in the last 6 years give 120 days of benefit, and each further 180 add 60, up to 720.',
