  'legal_notice.title': 'Legal notice · eslojusto.es',
  'legal_notice.description':
    'Who is behind eslojusto.es, and what its final settlement review does and does not do. It gives information about the law and does not give legal advice.',
  'legal_notice.h1': 'Legal notice',
  'legal_notice.who': 'Who is behind it',
