  'legal_notice.owner':
    'eslojusto.es is a personal project. These are the details of its owner (art. 10 of the Ley de Servicios de la Sociedad de la Información, the LSSI):',
  'legal_notice.seller': 'It is sold by {titular}, NIF {nif}, owner of eslojusto.es.',
