    'The agreed additional hours are {percent} % of the ordinary hours; the limit is {cap} %, and your collective agreement may raise it to up to {agreementMax} %.',
  'client.employment.calculation.part_time.complementary_notice':
    'You are given {days} of notice; the minimum is {minimum}, unless your collective agreement sets less.',
