    'The law provides for 2 extra payments a year; the other one may be spread over the monthly payslips.',
  'client.employment.calculation.extra_pays.prorated_by_agreement':
    'The extra payments are spread over the monthly payslips: art. 31 provides for this to be agreed in the collective agreement.',
  'client.employment.calculation.extra_pays.none_over_minimum':
    'Your pay for {year}, {annual} a year, reaches the SMI, which is {minimum}. Art. 31 gives the right to two extra payments, but their amount is set by your collective agreement, which may also spread them over the 12 payslips: your pay may already include them.',
  'client.employment.calculation.extra_pays.none_below_minimum':
    'Without extra payments, your pay for {year}, {annual} a year, does not reach the SMI, which is {minimum} and already counts the two extra payments (art. 31). That shortfall is counted in the minimum wage point; the amount of each extra payment is set by your collective agreement.',
  'client.employment.calculation.extra_pays.none_pay_unknown':
    'Art. 31 gives the right to two extra payments, and the collective agreement may spread them over the 12 payslips; without knowing your annual pay it cannot be checked whether they are included.',
  'client.employment.calculation.extra_pays.in_daily_minimum':
    "In a temporary contract of up to {days} paid by the day, the minimum per working day already includes the extra payments, Sundays and public holidays (art. 4.1 of each year's SMI royal decree).",
  'client.employment.calculation.extra_pays.may_be_in_daily_minimum':
    "For work of up to {days}, the minimum per working day may include the extra payments, Sundays and public holidays (art. 4.1 of each year's SMI royal decree): if your pay includes them, they are not missing.",
  'client.employment.calculation.clauses.months_unknown': 'You have not entered how long it lasts.',
