  'client.employment.calculation.clauses.waiver_holidays':
    'Waiver of holiday: the rights the law gives cannot be waived (art. 3.5).',
  'client.employment.calculation.clauses.waiver_salary':
    'Waiver of part of the pay: the rights the law gives cannot be waived (art. 3.5).',
