  'employment.documents.start_help':
    'You can upload your contract and your other work papers to fill in the data with what is read from them, or type it in yourself. Before anything is reviewed, you confirm each figure.',
  'employment.documents.upload':
    'Upload your contract and, if you have them, payslips, the job offer and your employment history',
  'employment.documents.files_hint':
    'The contract with its annexes and, if you have them, your payslips, the job offer or your employment history (vida laboral), in any order. Up to 25 photos or PDF pages in total. The photos and PDF pages are turned into images on your device before they are sent.',
  'employment.documents.consent':
    'I give my explicit consent for an AI to read these documents and fill in the form. I know they may include sensitive data, such as trade union membership, sick leave or a disability. They are read in the European Union and not stored.',
  'employment.pass.title': 'The detail, the report and the letter',
  'employment.pass.text':
    'For 4,99 € you see the step-by-step calculation of each point of your contract (year by year and payslip by payslip, with the law that applies and its source) and you download the PDF report and, if your review has points for it, the letter to the company. They are generated on your device.',
  'employment.pass.price':
    '4,99 €, VAT (IVA) included. A single payment, with no account or subscription. The pass lasts 7 days and only works in this browser, also for the final settlement and rent reviews: during that time you can redo or correct your review, read up to 15 document packs and see the detail again and download the report and the letter without paying again. On another device, in a private window or if you clear your browsing data, it is lost.',
  'employment.pass.paid_help':
    'If you paid from this browser and cannot see the detail or the downloads, recover your pass here. It only works in the browser you paid with.',
  'employment.pass.waiver':
    'I want to see the detail and the report now. I know that, as it is digital content delivered immediately, I lose the right of withdrawal (art. 103.m of the Ley General para la Defensa de los Consumidores y Usuarios, the general consumer protection law).',
  'employment.pass.download_information_letter':
    'Download the letter requesting the information in writing (PDF, free)',
  'employment.pass.download_certificate_request':
    'Download the request for the certificate of temporary contracts (PDF, free)',
  'employment.pass.download_company_letter': 'Download the letter to the company (PDF)',
  'employment.pass.letter_note':
    'The letters are templates. They are downloaded to your device and are not sent from here: whether and how you use them is your decision.',
