  'client.employment.letter.information.title': 'Information about my contract in writing',
  'client.employment.letter.information.on_request':
    'Under the {norma} (art. 3 and sole transitional provision), I can request in writing the information about my employment relationship and the company has 30 business days to provide it. I am requesting in writing the information I cannot find in my contract:',
  'client.employment.letter.information.before_start':
    'Under the {norma} (arts. 3 and 7.1), this information is given in writing before starting work. As I cannot find it in my contract, I am requesting it in writing:',
  'client.employment.letter.information.filename': 'eslojusto-carta-informacion.pdf',
  'client.employment.letter.pay.intro':
    'I have compared my pay with the salario mínimo interprofesional (SMI, the national minimum wage) for each year, and in these years it falls below it:',
  'client.employment.letter.pay.year':
    'In {anio}, the {norma} sets an annual minimum of {completo} for full-time hours. My agreed pay is {salario} a year: {diferencia} less a year.',
  'client.employment.letter.pay.year_prorata':
    'In {anio}, the {norma} sets an annual minimum of {completo} for full-time hours, which in proportion to my working hours is {minimo}. My agreed pay is {salario} a year: {diferencia} less a year.',
  'client.employment.letter.pay.day':
    'In {anio}, the {norma} sets a minimum of {completo} per legal working day for contracts of up to 120 days. My agreed pay is {salario} per working day: {diferencia} less per working day.',
  'client.employment.letter.pay.day_prorata':
    'In {anio}, the {norma} sets a minimum of {completo} per legal working day for contracts of up to 120 days, which in proportion to my working hours is {minimo}. My agreed pay is {salario} per working day: {diferencia} less per working day.',
  'client.employment.letter.pay.ask': 'I ask for my pay to be reviewed.',
