  'bills.documents.consent':
    'I give my explicit consent for an AI to read these documents and fill in the form. I know they may include personal data, such as names, addresses or account numbers. Of the supply point code (CUPS), only a fingerprint is kept to recognise a repeated bill. They are read in the European Union and not stored.',
  'bills.electricity.documents.start_help':
    'You can upload your electricity bills to fill in the data with what is read from them, or type it in yourself. Before anything is reviewed, you confirm each figure, bill by bill.',
  'bills.electricity.documents.upload': 'Upload one or more electricity bills',
  'bills.electricity.documents.files_hint':
    'All the pages of your electricity bills and, if you have them, the contract or a price change notice, in any order. Up to 25 photos or PDF pages in total. The photos and PDF pages are turned into images on your device before they are sent.',
  'bills.telecom.documents.start_help':
    'You can upload your contract and your phone or internet bills to fill in the data with what is read from them, or type it in yourself. Before anything is reviewed, you confirm each figure.',
  'bills.telecom.documents.upload':
    'Upload your contract and, if you have them, your phone or internet bills',
  'bills.telecom.documents.files_hint':
    'The contract or its minimum-term conditions and, if you have them, your bills: those with the penalty or from after the cancellation, and any other whose charges you want to go over, in any order. Up to 25 photos or PDF pages in total. The photos and PDF pages are turned into images on your device before they are sent.',
  'bills.pass.title': 'The report on your bills and the letter',
  'bills.pass.letter_note':
    'The letter is a template. It is downloaded to your device and is not sent from here: whether and how you use it is your decision.',
  'bills.pass.download_correction_letter':
    'Download the letter asking for a corrected invoice (PDF)',
  'bills.letter.legend': 'Your details for the letter (optional)',
  'bills.letter.id': 'DNI or NIE (optional)',
  'bills.letter.company': 'Electricity supplier',
  'bills.letter.reference': 'Contract number',
  'bills.letter.privacy':
    'These details are only used to fill in the letter on your device; they are not sent or stored.',
  'bills.telecom.charges.title': 'What you are charged',
  'bills.telecom.charges.lead':
    'Each line read from your bills, so that you can recognise everything you are charged. If you see something you did not sign up for yourself, ask your company.',
  'bills.telecom.charges.extras':
    'The lines marked «Extra» are premium-rate or third-party services: they are charged separately from your tariff. If you did not sign up for it yourself, ask your company.',
  'bills.telecom.charges.fees':
    'The bill does not say which of the fees is the one for your tariff: check that you recognise each fee.',
  'bills.telecom.charges.promotions': 'Discounts that are ending',
  'bills.telecom.charges.rights': 'What the regulations say',
  'bills.telecom.charges.disconnect':
    'You can ask your company to disconnect premium-rate services and international calls. It has to accept the request in writing, by phone or online, and disconnect them within 10 days at most; if it does not do so within that time for a reason not attributable to you, the cost of those services is borne by the company.',
  'bills.telecom.charges.unrequested':
    'If you did not ask for a service, the law does not allow you to be charged for it, and not replying to whoever provides it does not count as accepting it. If you did not sign up for it yourself, ask your company.',
  'bills.telecom.pass.title': 'The report and the letters',
  'bills.telecom.pass.letter_note':
    'The letters are templates. They are downloaded to your device and are not sent from here: whether and how you use them is your decision.',
  'bills.telecom.pass.download_exit_letter':
    'Download the letter about cancelling after a change of conditions (PDF, free)',
  'bills.telecom.pass.download_penalty_letter':
    'Download the letter asking for the penalty to be reviewed (PDF)',
  'bills.telecom.letters.title': 'Letter you can download free',
  'bills.telecom.letters.text':
    'This letter tells your operator when they notified you of the change and when you asked to cancel, without figures, and can be downloaded free. It is generated on your device.',
  'bills.telecom.letter.legend': 'Your details for the letters (optional)',
  'bills.telecom.letter.company': 'Operator',
  'bills.telecom.letter.reference': 'Customer or contract number',
  'bills.telecom.letter.privacy':
    'These details are only used to fill in the letters on your device; they are not sent or stored.',
  'bills.pass.price':
    '4,99 €, VAT (IVA) included. A single payment, with no account or subscription. The pass lasts 7 days and only works in this browser: during that time you can read up to 15 document packs, in any section, and download the report again without paying again. On another device, in a private window or if you clear your browsing data, it is lost.',
  'bills.basket.memory':
    'We do not store anything: your year lives only in this tab. If you close or reload it, upload your bills again. If you pay, the bills you have already reviewed wait in this tab while you are on the payment page and all come back with you; bills that have been read but not yet reviewed do not.',
