  'client.credit.letter.reference': 'Contract number',
  'client.credit.letter.regards': 'Kind regards.',
  'client.credit.letter.about.personal_loan':
    'I am writing to you about my personal loan, which I took out on {fecha}.',
  'client.credit.letter.about.car_loan':
    'I am writing to you about the loan with which I financed the purchase of a car, which I took out on {fecha}.',
  'client.credit.letter.about.revolving':
    'I am writing to you about my deferred payment (revolving) card, which I took out on {fecha}.',
  'client.credit.letter.information.title': 'Request for information about my credit',
  'client.credit.letter.information.schedule':
    'Art. 16.2.i of Ley 16/2011, on consumer credit contracts, sets out the right to receive, on request, free of charge and at any time during the contract, a statement in the form of a repayment schedule. I ask you for the repayment schedule of my credit.',
  'client.credit.letter.information.breakdown':
    'I ask you for a breakdown of what I have paid to date, with the part that has gone to interest, to fees and to capital, and of what remains to be paid. The banking transparency order (orden de transparencia bancaria) provides for this breakdown for deferred payment cards.',
  'client.credit.letter.information.reply':
    'You can send it to me in writing, by the means you use to communicate with me.',
  'client.credit.letter.information.filename': 'eslojusto-carta-informacion-credito.pdf',
  'client.credit.letter.repayment.title':
    'Review of the compensation for repaying the credit early',
  'client.credit.letter.repayment.body':
    'On {fecha} I repaid {capital} of capital early and you charged me {cobrado} as compensation for that early repayment. The agreed end date of the credit was {fin}.',
  'client.credit.letter.repayment.over_a_year':
    'Between that day and the agreed end date more than a year was left, counted from date to date, so the law sets as a cap 1 % of the amount repaid (art. 30.2 of Ley 16/2011, on consumer credit contracts).',
  'client.credit.letter.repayment.up_to_a_year':
    'Between that day and the agreed end date a year or less was left, counted from date to date, so the law sets as a cap 0,5 % of the amount repaid (art. 30.2 of Ley 16/2011, on consumer credit contracts).',
  'client.credit.letter.repayment.base_with_interest':
    'On {base}, the capital plus the interest settled that day, the cap is {tope}.',
  'client.credit.letter.repayment.base_principal':
    'On {base}, the capital repaid, the cap is {tope}.',
  'client.credit.letter.repayment.interest_cap':
    'In addition, the compensation cannot exceed the interest that was still to be paid (art. 30.5): the cap is {tope}.',
  'client.credit.letter.repayment.over':
    'The compensation charged exceeds that cap by {diferencia}.',
  'client.credit.letter.repayment.ask':
    'I ask you to review this compensation or, if it is based on a greater loss caused by the repayment, to justify it to me, as provided for in art. 30.4.',
  'client.credit.letter.repayment.paid_by_insurance':
    'The repayment was paid by an insurance policy, and for that case the law does not allow a compensation to be charged (art. 30.3 of Ley 16/2011, on consumer credit contracts).',
  'client.credit.letter.repayment.variable_rate':
    'In that period the interest rate was not fixed, and for that case the law does not allow a compensation to be charged (art. 30.3 of Ley 16/2011, on consumer credit contracts).',
  'client.credit.letter.repayment.ask_no_basis': 'I ask you to review this charge.',
  'client.credit.letter.repayment.lowest':
    'Which amount the cap is calculated on allows two readings: these figures are those of the reading that gives the smaller difference.',
  'client.credit.letter.repayment.filename': 'eslojusto-carta-compensacion-credito.pdf',
  'client.credit.report.title': 'Review of your loan or card',
  'client.credit.report.intro':
    'This report compares the figures of your credit with what the law says, item by item, with the details you confirmed in the review: the APR (TAE) that comes from them, how it compares with the Banco de España average rate, the cap for repaying early and the time limit for withdrawal. Where the result depends on a detail you do not know, it gives each reading. It provides information about the law and is not legal advice.',
  'client.credit.report.footer':
    'eslojusto.es provides information about your rights and does not give advice. Laws, interpretations and average rates as they stood on {fecha}.',
  'client.credit.report.filename': 'eslojusto-informe-credito.pdf',
