  'client.household.warning.night_notice':
    'For someone who lives in the home, the decision to end the relationship may not be carried out between 17:00 and 08:00, except for a very serious breach of the duties of loyalty and trust (art. 11.4). The review looks at the time you were told.',
  'client.household.ending_unknown':
    "As you don't know how it ended, the ending has not been reviewed: not the dismissal by withdrawal, the severance pay, the notice period or what remains to be paid.",
