  'client.insurance.calculation.non_renewal.last_day':
    'Your policy expires on {expiry}. The law requires notice in writing that you are not renewing it at least one month in advance: the last day is {day}.',
  'client.insurance.calculation.non_renewal.days_left': 'That is in {days}.',
