  'client.insurance.calculation.non_renewal.ended': 'That time limit ended on {day}.',
  'client.insurance.calculation.non_renewal.arrive_by':
    'The review assumes the letter has to reach the insurer by {day} at the latest: the law does not make clear whether sending it on that day is enough.',
  'client.insurance.calculation.non_renewal.midnight':
    'If your policy expires at 00:00 h on that day, it can be read that the period ends the day before, and the time limit would be one day shorter. The policy has to state the day and time at which its effects end (art. 8 of the Ley de Contrato de Seguro), but no rule says how this case is counted: it is an interpretation.',
  'client.insurance.calculation.non_renewal.month_end':
    'The month before the expiry date does not have that same day, so its last day is taken. No rule settles this case when counting backwards: it is an interpretation, and that is why the earliest day is given.',
  'client.insurance.calculation.non_renewal.extension_assumed':
    "As you don't know whether your policy renews automatically, it is calculated as if it did; your policy says which.",
  'client.insurance.calculation.non_renewal.no_extension':
    'Your policy does not renew automatically: it ends on its date and there is no renewal to object to.',
  'client.insurance.calculation.change_notice.deadline':
    'The insurer has to notify you of any change to the contract two months before the expiry date: by {day} at the latest.',
