  'client.insurance.calculation.withdrawal.compulsory_excluded':
    'The law excludes from withdrawal insurance with which you meet an obligation to be insured, such as compulsory car insurance.',
  'client.insurance.calculation.withdrawal.voluntary_unverified':
    'Your policy also includes voluntary cover. It has not been checked in an official source whether you can withdraw from that cover alone, so no date is given.',
  'client.insurance.calculation.withdrawal.mortgage_duty':
    'If your mortgage requires you to insure the home, this insurance meets an obligation to be insured: mortgaged property has to be insured against damage (art. 8 of Ley 2/1981). The law excludes from withdrawal insurance with which you meet such an obligation, but it does not say whether that covers the whole policy or only that cover, so no date is given.',
  'client.insurance.calculation.information.policy_correction':
    'If the policy does not match what you asked for or what you agreed, the law gives you one month from when it is delivered to you to ask the insurer to correct it; after that month, what the policy says applies.',
